  "implementation": "def solve(case):
    lines = case['lines']
    trajectory = []
    error_line = None
    previous_type = None
    allowed_types = {'Thought', 'Action', 'Observation', 'Final'}
    for i, line in enumerate(lines):
        parts = line.split(': ', 1)
        if len(parts) == 2:
            typ, content = parts[0].strip(), parts[1].strip()
        else:
            typ, content = 'unknown', line
        trajectory.append({'type': typ, 'content': content})
        if error_line is not None:
            previous_type = typ
            continue
        if typ not in allowed_types:
            error_line = i
        elif i == 0 and typ not in ('Thought', 'Final'):
            error_line = i
        elif previous_type == 'Action' and typ != 'Observation':
            error_line = i
        elif previous_type == 'Observation' and typ not in ('Thought', 'Final'):
            error_line = i
        elif previous_type == 'Thought' and typ not in ('Action', 'Final'):
            error_line = i
        elif previous_type == 'Final':
            error_line = i
        previous_type = typ
    if error_line is None:
        if len(lines) == 0 or trajectory[-1]['type'] != 'Final':
            error_line = len(lines) - 1 if lines else 0
    valid = error_line is None
    return {'valid': valid, 'error_line': error_line, 'trajectory': trajectory}"
}
